# 11a_simB_truth.R: Simulation B community generator and INDEPENDENT truth. Species abundance matrices are simulated (not dissimilarities).
#   200 species along a productivity gradient x in [0,1]: 120 environmental specialists (narrow Gaussian niches, sd 0.07, optima evenly spaced -0.05..1.05) and 80 generalists (broad niches, sd 0.35, optima 0..1);
#   within-guild baseline abundances lognormal(0, 0.5) (fixed seed). Local relative abundance p_s(x) = pi_g(x) * a_s N_s(x) / sum_{s' in guild g} a_s' N_s'(x).
#   Scenario "logistic": generalist dominance pi_gen(x) = 0.1 + 0.8 * plogis(10 (x - 0.5)) increases continuously along the gradient; scenario "control": pi_gen = 0.5 at every x.
#   Local community = multinomial sample of exactly N = 2000 individuals (constant total abundance) from p(x).
# Independent truth: for matched profiles (k sites at x = m + h q, q fixed, mean pairwise |difference| = 1) the expected response is the Monte Carlo mean (R = 300 multinomial replicates per profile) of the
# package response functions (incidence, relative abundance, occupancy-associated and heterogeneity components) applied to simulated counts; it uses no fitted model. Run from final/ (ZG_LIB6 set).
source("revision_sim/00_sim_common.R"); SEED_POOL <- 777; N_TOT <- 2000L; N_SPEC <- 120; N_GEN <- 80; R_MC <- 300L; ORDERS <- c(2, 3, 4, 5, 8); MU_P <- .5; SD_P <- 1 / sqrt(12)
set.seed(SEED_POOL); sp <- data.frame(species = sprintf("sp%03d", 1:(N_SPEC + N_GEN)), guild = rep(c("specialist", "generalist"), c(N_SPEC, N_GEN)), opt = c(seq(-.05, 1.05, length.out = N_SPEC), seq(0, 1, length.out = N_GEN)), sd = rep(c(.07, .35), c(N_SPEC, N_GEN)), a = exp(rnorm(N_SPEC + N_GEN, 0, .5)))
pi_gen <- function(x, scn) if (scn == "logistic") .1 + .8 * plogis(10 * (x - .5)) else rep(.5, length(x))
comm_p <- function(x, scn) { N <- exp(-0.5 * outer(x, sp$opt, "-")^2 / rep(sp$sd, each = length(x))^2) * rep(sp$a, each = length(x)); g <- sp$guild == "generalist"; pg <- pi_gen(x, scn); out <- matrix(0, length(x), nrow(sp)); out[, g] <- (1 - 0) * pg * N[, g] / rowSums(N[, g, drop = FALSE]); out[, !g] <- (1 - pg) * N[, !g] / rowSums(N[, !g, drop = FALSE]); colnames(out) <- sp$species; out }
write.csv(sp, "revision_sim/tables/simB_species.csv", row.names = FALSE)
xg <- seq(0, 1, length.out = 101); write.csv(bind_rows(lapply(c("logistic", "control"), function(s) data.frame(scenario = s, x = xg, generalist_dominance = pi_gen(xg, s)))), "revision_sim/tables/simB_guild_dominance.csv", row.names = FALSE)
nich <- expand.grid(x = xg, i = seq_len(nrow(sp))); nich$niche <- exp(-0.5 * ((nich$x - sp$opt[nich$i]) / sp$sd[nich$i])^2); nich$guild <- sp$guild[nich$i]; nich$species <- sp$species[nich$i]; write.csv(nich[, c("species", "guild", "x", "niche")], "revision_sim/tables/simB_niche_curves.csv", row.names = FALSE)
RESP_NAMES <- c("incidence", "relative", "occupancy", "heterogeneity")
resp_all <- function(cnt, idx) { ri <- ugdm_response(cnt, idx, "relative"); rt <- ugdm_response(cnt, idx, "total"); cr <- unclass(ugdm_component_response(cnt, idx)); list(incidence = rt$y, relative = ri$y, occupancy = cr[, "occupancy"], heterogeneity = cr[, "heterogeneity"], total_component = cr[, "total"], keep = rt$keep & ri$keep, trials_inc = rt$trials) }
mc_truth <- function(scn, k) { grid <- data.frame(m = MU_P + SD_P * GRID_STD$m, h = SD_P * GRID_STD$h, m_std = GRID_STD$m, h_std = GRID_STD$h); q <- prof_q(k); out <- list(); set.seed(SEED_POOL + 100 * k + (scn == "control"))
  for (i in seq_len(nrow(grid))) { xs <- grid$m[i] + grid$h[i] * q; P <- comm_p(xs, scn); cnt <- do.call(rbind, lapply(seq_len(k), function(j) t(rmultinom(R_MC, N_TOT, P[j, ])))); idx <- matrix(rep(seq_len(R_MC), k) + rep((0:(k - 1)) * R_MC, each = R_MC), R_MC, k); colnames(cnt) <- sp$species; rr <- resp_all(cnt, idx); ok <- rr$keep
    out[[i]] <- data.frame(grid[i, ], incidence = mean(rr$incidence[ok]), relative = mean(rr$relative[ok]), occupancy = mean(rr$occupancy[ok], na.rm = TRUE), heterogeneity = mean(rr$heterogeneity[ok], na.rm = TRUE), total_component = mean(rr$total_component[ok]), prop_defined = mean(ok),
      mc_se_relative = sd(rr$relative[ok]) / sqrt(sum(ok)), mc_se_incidence = sd(rr$incidence[ok]) / sqrt(sum(ok))) }; cbind(scenario = scn, order = k, do.call(rbind, out)) }
if (sys.nframe() == 0 || identical(Sys.getenv("RUN_TRUTH", "1"), "1")) { T_ <- bind_rows(mclapply(expand.grid(scn = c("logistic", "control"), k = ORDERS, stringsAsFactors = FALSE) |> split(seq_len(10)), function(z) mc_truth(z$scn, z$k), mc.cores = 9)); write.csv(T_, "revision_sim/tables/simB_truth_surfaces.csv", row.names = FALSE); print(head(T_ |> filter(order == 2, scenario == "logistic", h_std == 1.2), 7), digits = 3) }
